import sys, re; f=open(sys.argv[1]).read(); concepts=set(re.findall(r'Concept ([a-z-]+)', f)); evals=len(re.findall(r'Evaluation', f)); findings=len(re.findall(r'Finding', f)); theories=len(re.findall(r'Theory', f)); nums=[float(x) for x in re.findall(r'Number ([0-9.]+)', f)]; truths=[float(x) for x in re.findall(r'stv ([0-9.]+)', f)]; vals=truths+nums; avg=sum(vals)/len(vals) if vals else 0; structural=len(concepts)+evals+findings+theories; sources=len(re.findall(r'Source', f)); print('=== VERIFICATION ==='); print('Concepts:', len(concepts)); print('Evaluations:', evals); print('Findings:', findings); print('Theories:', theories); print('Sources:', sources); print('Numeric values:', len(vals)); print('Avg truth:', round(avg, 3)); print('Structural score:', structural); result='PASSED' if structural > 10 else 'FAILED'; print('Result:', result)